describe("User", () => {
  it("creates a user with name and age", () => {
    let user = new User("Alex", 25);
    expect(user.name).toBe("Alex");
    expect(user.age).toBe(25);
  });

  it("throws error for negative age", () => {
    expect(() => new User("Alex", -1)).toThrow("Invalid age");
  });

  it("returns correct greeting", () => {
    let user = new User("Alex", 25);
    expect(user.greet()).toContain("Alex");
  });

  it("defaults to guest name", () => {
    let user = new User();
    expect(user.name).toBe("Guest");
  });
});

import { test, expect, vi } from "vitest";

// Test async function
test("fetchUser returns user data", async () => {
  let user = await fetchUser(1);
  expect(user).toHaveProperty("name");
  expect(user.id).toBe(1);
});

// Test Promise rejection
test("fetchUser rejects for invalid ID", async () => {
  await expect(fetchUser(-1)).rejects.toThrow("Invalid ID");
});

// Test with fake timers
test("delay resolves after specified time", async () => {
  vi.useFakeTimers();
  let promise = delay(1000);
  vi.advanceTimersByTime(1000);
  await expect(promise).resolves.toBeUndefined();
  vi.useRealTimers();
});

// @vitest-environment happydom
import { test, expect, beforeEach } from "vitest";
import { createApp } from "./app.js";

beforeEach(() => {
  document.body.innerHTML = "";
});

test("app adds a greeting to the page", () => {
  createApp();
  let heading = document.querySelector("h1");
  expect(heading).not.toBeNull();
  expect(heading.textContent).toContain("Hello");
});

test("button click increments counter", () => {
  createApp();
  let btn = document.querySelector("#increment");
  let display = document.querySelector("#count");
  btn.click();
  expect(display.textContent).toBe("1");
});
